import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
    } finally {
      setLoading(false);
    }
  };

  // Stats
  const stats = [
    { label: 'Total Problems', value: problems.length, icon: '📚' },
    { label: 'Solved', value: user?.stats?.problemsSolved || 0, icon: '✅' },
    { label: 'Attempts', value: user?.stats?.totalAttempts || 0, icon: '📝' },
    { label: 'Success Rate', value: user?.stats?.totalAttempts > 0 
        ? Math.round((user.stats.problemsSolved / user.stats.totalAttempts) * 100) 
        : 0, icon: '🏆', suffix: '%' },
  ];

  return (
    <div style={styles.container}>
      {/* Top Bar - Like TOOFAAN */}
      <div style={styles.topBar}>
        <div style={styles.topBarLeft}>
          <span style={styles.logo}>⚡ CodeArena</span>
          <span style={styles.topBarSeparator}>|</span>
          <span style={styles.topBarTitle}>Dashboard</span>
          <span style={styles.topBarSeparator}>|</span>
          <span style={styles.topBarLink}>Assignments</span>
          <span style={styles.topBarSeparator}>|</span>
          <span style={styles.topBarLink}>Completed Tasks</span>
          <span style={styles.topBarSeparator}>|</span>
          <span style={styles.topBarLink}>Today's Titans</span>
          <span style={styles.topBarSeparator}>|</span>
          <span style={styles.topBarLink}>More ▼</span>
        </div>
        <div style={styles.topBarRight}>
          <button style={styles.refreshBtn} onClick={() => window.location.reload()}>
            🔄 REFRESH
          </button>
          <span style={styles.weather}>29°</span>
        </div>
      </div>

      {/* Stats Row */}
      <div style={styles.statsRow}>
        {stats.map((stat, index) => (
          <div key={index} style={styles.statItem}>
            <span style={styles.statIcon}>{stat.icon}</span>
            <span style={styles.statValue}>{stat.value}{stat.suffix || ''}</span>
            <span style={styles.statLabel}>{stat.label}</span>
          </div>
        ))}
      </div>

      {/* Problems Section */}
      <div style={styles.problemsSection}>
        <h2 style={styles.sectionTitle}>📋 Assignments</h2>
        
        <div style={styles.problemGrid}>
          {loading ? (
            <div style={styles.loadingText}>Loading...</div>
          ) : problems.length === 0 ? (
            <div style={styles.emptyState}>No assignments available</div>
          ) : (
            problems.map((problem, index) => (
              <div key={problem._id} style={styles.problemCard}>
                <div style={styles.programNumber}>
                  PROGRAM-{index + 1}
                </div>
                
                <div style={styles.problemTitle}>
                  {problem.title}
                </div>
                
                <div style={styles.problemMeta}>
                  <span style={styles.problemId}>FS-A1-Audi-2027</span>
                  <span style={styles.problemLab}>LAB</span>
                </div>
                
                <div style={styles.startedInfo}>
                  <span style={styles.startedLabel}>STARTED</span>
                  <span style={styles.startedDate}>
                    on {new Date(problem.createdAt).toLocaleDateString('en-US', { 
                      weekday: 'long',
                      day: 'numeric', 
                      month: 'long', 
                      year: 'numeric' 
                    })}
                  </span>
                </div>
                
                <div style={styles.difficultyRow}>
                  <span style={{
                    ...styles.difficultyBadge,
                    background: problem.difficulty === 'Easy' ? '#4CAF50' :
                               problem.difficulty === 'Medium' ? '#FF9800' : '#f44336',
                  }}>
                    {problem.difficulty || 'Easy'}
                  </span>
                </div>
                
                <button 
                  style={styles.attemptBtn}
                  onClick={() => navigate(`/problems/${problem._id}`)}
                  onMouseEnter={(e) => e.currentTarget.style.background = '#6C63FF'}
                  onMouseLeave={(e) => e.currentTarget.style.background = '#4A3FCF'}
                >
                  ATTEMPT →
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f6fa',
    fontFamily: 'Inter, -apple-system, sans-serif',
    padding: '0',
  },
  
  topBar: {
    background: 'white',
    padding: '14px 30px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    borderBottom: '1px solid #e8e8e8',
    flexWrap: 'wrap',
    gap: '10px',
  },
  topBarLeft: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    flexWrap: 'wrap',
  },
  logo: {
    fontSize: '18px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  topBarSeparator: {
    color: '#ccc',
    fontSize: '14px',
  },
  topBarTitle: {
    fontSize: '14px',
    fontWeight: 600,
    color: '#1a1a2e',
  },
  topBarLink: {
    fontSize: '14px',
    color: '#666',
    cursor: 'pointer',
  },
  topBarRight: {
    display: 'flex',
    alignItems: 'center',
    gap: '15px',
  },
  refreshBtn: {
    padding: '6px 16px',
    background: '#6C63FF',
    color: 'white',
    border: 'none',
    borderRadius: '6px',
    fontSize: '12px',
    fontWeight: 600,
    cursor: 'pointer',
    letterSpacing: '0.3px',
  },
  weather: {
    fontSize: '16px',
    fontWeight: 500,
    color: '#333',
  },

  statsRow: {
    display: 'flex',
    gap: '30px',
    padding: '20px 30px',
    background: 'white',
    borderBottom: '1px solid #e8e8e8',
    flexWrap: 'wrap',
  },
  statItem: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
  },
  statIcon: {
    fontSize: '20px',
  },
  statValue: {
    fontSize: '20px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  statLabel: {
    fontSize: '14px',
    color: '#888',
    marginLeft: '2px',
  },

  problemsSection: {
    padding: '24px 30px',
  },
  sectionTitle: {
    fontSize: '18px',
    fontWeight: 600,
    color: '#1a1a2e',
    marginBottom: '20px',
  },

  problemGrid: {
    display: 'grid',
